static std::size_t checks = 0;
static void require(bool value) {
    ++checks;
    if (!value) std::abort();
}

template <bool Strict, class T>
static std::size_t reference_length(const std::vector<T>& values) {
    std::vector<std::size_t> dp(values.size(), 1);
    std::size_t result = 0;
    for (std::size_t i = 0; i < values.size(); ++i) {
        for (std::size_t j = 0; j < i; ++j) {
            if (Strict ? values[j] < values[i] : !(values[i] < values[j]))
                dp[i] = std::max(dp[i], dp[j] + 1);
        }
        result = std::max(result, dp[i]);
    }
    return result;
}

template <bool Strict, class Index, class T>
static auto inspect_width(const std::vector<T>& values, std::size_t expected) {
    auto indices = reinsirk::detail::LISIndicesImpl<Strict, Index>(values);
    require(indices.size() == expected);
    for (std::size_t i = 0; i < indices.size(); ++i) {
        require(indices[i] < values.size());
        if (i != 0) {
            require(indices[i - 1] < indices[i]);
            require(Strict ? values[indices[i - 1]] < values[indices[i]]
                           : !(values[indices[i]] < values[indices[i - 1]]));
        }
    }
    return indices;
}

template <bool Strict, class T>
static void inspect(const std::vector<T>& values) {
    const auto length = reference_length<Strict>(values);
    const auto wide = inspect_width<Strict, std::size_t>(values, length);
    const auto compact = inspect_width<Strict, std::uint32_t>(values, length);
    // 格納幅による復元列の変化も確認する。解の独立判定は上のDPで行う。
    require(wide == compact);
    require(LISIndices<Strict>(values) == wide);
    if (values.size() <= 256)
        require(inspect_width<Strict, std::uint8_t>(values, length) == wide);
}

template <class T>
static void inspect_both(const std::vector<T>& values) {
    inspect<true>(values);
    inspect<false>(values);
}

