    MoveOnly& operator=(const MoveOnly&) = delete;
    MoveOnly(MoveOnly&&) = default;
    MoveOnly& operator=(MoveOnly&&) = default;
    friend bool operator<(const MoveOnly& lhs, const MoveOnly& rhs) {
        // 同値の別表現を含む降順の狭義弱順序。operator==は定義しない。
        return lhs.key / 3 > rhs.key / 3;
    }
};

template <bool Strict>
static void check_overflow() {
    bool rejected = false;
    try {
        (void)reinsirk::detail::LISIndicesImpl<Strict, std::uint8_t>(
            std::vector<int>(257, 0));
    } catch (const std::length_error&) {
        rejected = true;
    }
    require(rejected);
}

template <bool Strict>
static void large_storage_edges() {
    // 既知の単調列で幅の代替経路と作業領域の切り替えを確認する。
    for (std::size_t n : {4095u, 4096u, 4097u, 8193u}) {
        for (bool constant : {false, true}) {
            std::vector<std::int64_t> values(n);
            for (std::size_t i = 0; i < n; ++i)
                values[i] = constant ? 7 : static_cast<std::int64_t>(i);
            const auto length = constant && Strict ? std::size_t{1} : n;
            const auto wide = inspect_width<Strict, std::size_t>(values, length);
            require(inspect_width<Strict, std::uint32_t>(values, length) == wide);
            require(LISIndices<Strict>(values) == wide);
        }
        const std::vector<bool> bits(n, false);
        const auto length = Strict ? std::size_t{1} : n;
        const auto wide = inspect_width<Strict, std::size_t>(bits, length);
        require(inspect_width<Strict, std::uint32_t>(bits, length) == wide);
        require(LISIndices<Strict>(bits) == wide);
    }
}

int main() {
    std::mt19937_64 generator(728396);
    for (std::size_t n : {0u, 1u, 2u, 3u, 63u, 64u, 65u, 127u, 128u,
                          129u, 254u, 255u, 256u, 257u, 511u}) {
        for (unsigned shape = 0; shape < 6; ++shape) {
            std::vector<int> values(n);
            for (std::size_t i = 0; i < n; ++i) {
                values[i] = shape == 0 ? static_cast<int>(i)
                          : shape == 1 ? -static_cast<int>(i)
                          : shape == 2 ? 5
                          : shape == 3 ? static_cast<int>(i % 3)
                          : shape == 4 ? static_cast<int>((n - i) / 2)
                                       : static_cast<int>(generator() % 41) - 20;
            }
            inspect_both(values);
            std::vector<MoveOnly> custom;
            for (const auto value : values) custom.emplace_back(value);
            inspect_both(custom);
        }
        std::vector<bool> bits(n);
        for (std::size_t i = 0; i < n; ++i) bits[i] = generator() % 3 != 0;
        inspect_both(bits);
    }
    check_overflow<true>();
    check_overflow<false>();
    large_storage_edges<true>();
    large_storage_edges<false>();
#ifndef SKIP_RUNTIME_CHECKS
    for (bool strict : {false, true}) {
        std::vector<double> values(129, 1.0);
        values.back() = std::numeric_limits<double>::quiet_NaN();
        bool rejected = false;
        try {
            if (strict)
                (void)reinsirk::detail::LISIndicesImpl<true, std::size_t>(values);
            else
                (void)reinsirk::detail::LISIndicesImpl<false, std::size_t>(values);
        } catch (const std::invalid_argument&) {
            rejected = true;
        }
        require(rejected);
    }
#endif
    std::printf("PASS %ju checks; compact/fallback widths, max index, overflow, generic types\n",
                static_cast<std::uintmax_t>(checks));
}
